'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { BuildingOfficeIcon, PlusIcon, MagnifyingGlassIcon, PencilIcon, TrashIcon } from '@heroicons/react/24/outline';
import { formatNumber, formatDate } from '@/lib/utils';
import apiClient, { endpoints } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';

// Types (matches API)
interface Branch {
  id: string;
  name: string;
  code: string;
  address?: string;
  phone?: string;
  email?: string;
  manager_id?: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export default function BranchesPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [branches, setBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchBranches = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(endpoints.branches);
      setBranches(response.data || []);
      setLoading(false);
    } catch (err) {
      console.error('Fetch branches error:', err);
      setError('Failed to load branches. Please ensure the API is accessible.');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBranches();
  }, []);

  const filteredBranches = branches.filter(branch =>
    branch.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    branch.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div>
              <h1 className="text-2xl font-bold text-primary">Branches</h1>
              <p className="mt-1 text-sm text-text-secondary">
                Manage your store locations and their inventory
              </p>
            </div>
            <Button>
              <PlusIcon className="h-5 w-5 mr-2" />
              Add Branch
            </Button>
          </div>

          {/* Search */}
          <div className="card p-4">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-5 w-5 text-text-secondary" />
              </div>
              <Input
                type="text"
                placeholder="Search by name or code..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>

          {/* Error State */}
          {error && (
            <div className="bg-error-light border border-error/20 rounded-lg p-4 flex items-center justify-between">
              <p className="text-error text-sm">{error}</p>
              <Button variant="outline" size="sm" onClick={fetchBranches}>
                Retry
              </Button>
            </div>
          )}

          {/* Branches Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {loading ? (
              [...Array(3)].map((_, i) => (
                <div key={i} className="card p-6 animate-pulse">
                  <div className="h-6 bg-surface rounded w-3/4 mb-4"></div>
                  <div className="h-4 bg-surface rounded w-1/2 mb-2"></div>
                  <div className="h-4 bg-surface rounded w-2/3 mb-4"></div>
                  <div className="h-10 bg-surface rounded w-full"></div>
                </div>
              ))
            ) : filteredBranches.length > 0 ? (
              filteredBranches.map((branch) => (
                <div key={branch.id} className="card p-6 hover-lift">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3">
                        <h3 className="text-lg font-bold text-primary">{branch.name}</h3>
                        <Badge variant={branch.is_active ? 'success' : 'error'}>
                          {branch.is_active ? 'Active' : 'Inactive'}
                        </Badge>
                      </div>
                      <p className="text-sm text-text-secondary mt-1 font-semibold">Code: {branch.code}</p>
                      <p className="text-sm text-text-secondary mt-2 line-clamp-1">{branch.address}</p>
                      <p className="text-sm text-text-secondary">{branch.phone}</p>
                    </div>
                    <div className="flex flex-col space-y-2">
                      <Button variant="ghost" size="icon">
                        <PencilIcon className="h-4 w-4 text-text-secondary" />
                      </Button>
                      <Button variant="ghost" size="icon">
                        <BuildingOfficeIcon className="h-4 w-4 text-primary" />
                      </Button>
                    </div>
                  </div>
                  <div className="mt-4 pt-4 border-t border-divider flex justify-between items-center text-xs text-text-secondary">
                    <span>Created {formatDate(branch.created_at)}</span>
                    <Button variant="link" size="sm" className="h-auto p-0">View Details</Button>
                  </div>
                </div>
              ))
            ) : (
              <div className="col-span-full card py-12 text-center text-text-secondary">
                <BuildingOfficeIcon className="h-12 w-12 mx-auto mb-4 opacity-20" />
                <p>No branches found matching your search</p>
              </div>
            )}
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
